import { config } from '../config/env';
import { isEnglish, languageInfo, LITTLE_CLOUD_VOICE_ID } from '../data/languages';
import { wordFor } from '../data/levels';
import type { GameObjectDef, LangCode } from '../data/types';
import { useGame } from '../game/store';
import { audio } from './AudioEngine';

/**
 * Pronunciation pipeline, best source first:
 *   1. an explicit per-object audio file from the level data,
 *   2. a clip pre-generated by `npm run generate:audio` (listed in /audio/manifest.json),
 *   3. the live Fish Audio proxy (dev or Vercel) with an explicit kid voice id,
 *   4. browser speech only for non-object lines when the proxy is unavailable.
 *
 * Object taps never use the browser — OS Italian/etc. voices are usually adult men.
 */

let manifest: Promise<Set<string>> | null = null;
function loadManifest() {
  manifest ??= fetch('/audio/manifest.json')
    .then((r) => (r.ok ? r.json() : { files: [] }))
    .then((m: { files?: string[] }) => new Set(m.files ?? []))
    .catch(() => new Set<string>());
  return manifest;
}

/** null = not probed yet / unknown; true/false once /api/tts/status answers. */
let proxy: Promise<boolean | null> | null = null;
function proxyStatus() {
  if (!config.ttsProxy) return Promise.resolve(false);
  proxy ??= fetch('/api/tts/status')
    .then((r) => (r.ok ? r.json() : null))
    .then((s: { enabled?: boolean } | null) => (s ? !!s.enabled : null))
    .catch(() => null);
  return proxy;
}

/** Warm up lookups so the first tap speaks without delay. */
export function primeSpeech() {
  void loadManifest();
  void proxyStatus();
  if ('speechSynthesis' in window) window.speechSynthesis.getVoices();
}

let generation = 0;

export function stopSpeech() {
  generation++;
  audio.stopVoice();
  if ('speechSynthesis' in window) window.speechSynthesis.cancel();
}

function pickVoice(lang: LangCode): SpeechSynthesisVoice | undefined {
  const tag = languageInfo(lang).bcp47.toLowerCase();
  const voices = window.speechSynthesis.getVoices();
  const base = tag.split('-')[0];
  const forLang = voices.filter((v) => v.lang.toLowerCase() === tag || v.lang.toLowerCase().startsWith(base));
  return (
    forLang.find((v) => /child|kid|girl|boy|soft|female|woman|zira|samantha|karen|moira|fiona/i.test(v.name)) ??
    forLang.find((v) => /natural|enhanced|premium|google/i.test(v.name)) ??
    forLang[0]
  );
}

function speakWithBrowser(text: string, lang: LangCode): Promise<void> {
  if (!config.speechFallback || !('speechSynthesis' in window)) return Promise.resolve();
  return new Promise((resolve) => {
    const u = new SpeechSynthesisUtterance(text);
    u.lang = languageInfo(lang).bcp47;
    const voice = pickVoice(lang);
    if (voice) u.voice = voice;
    u.rate = 0.88;
    u.pitch = 1.35;
    const done = () => {
      clearTimeout(guard);
      resolve();
    };
    const guard = setTimeout(done, 4000 + text.length * 120);
    u.onend = done;
    u.onerror = done;
    window.speechSynthesis.speak(u);
  });
}

function ttsUrl(text: string, lang: LangCode, voiceId: string) {
  return `/api/tts?lang=${encodeURIComponent(lang)}&text=${encodeURIComponent(text)}&voice=${encodeURIComponent(voiceId)}`;
}

async function resolveClip(
  text: string,
  lang: LangCode,
  clipId: string | undefined,
  override: string | undefined,
  voiceId: string,
) {
  if (audio.isMuted || !audio.context) return null;
  if (override) {
    const buf = await audio.load(override);
    if (buf) return buf;
  }
  if (clipId && (await loadManifest()).has(`${lang}/${clipId}`)) {
    const buf = await audio.load(`/audio/${lang}/${clipId}.mp3`);
    if (buf) return buf;
  }
  // Always try Fish when the proxy flag is on — don't wait on /status (it 404s on
  // some deploys and previously forced adult browser voices for every object).
  if (config.ttsProxy) {
    const status = await proxyStatus();
    if (status !== false) {
      const buf = await audio.load(ttsUrl(text, lang, voiceId));
      if (buf) return buf;
    }
  }
  return null;
}

type SayOpts = {
  /** When false, never use OS speech (object taps — keeps Fish kid voices only). */
  allowBrowser?: boolean;
};

/** Speak a phrase. Resolves when finished (or immediately if superseded or muted). */
export async function say(
  text: string,
  lang: LangCode,
  clipId?: string,
  override?: string,
  voiceId: string = languageInfo(lang).voiceId,
  opts: SayOpts = {},
): Promise<void> {
  const mine = ++generation;
  if (audio.isMuted) return;
  const clip = await resolveClip(text, lang, clipId, override, voiceId);
  if (mine !== generation) return;
  if (clip) {
    await audio.playVoice(clip);
    return;
  }
  const allowBrowser = opts.allowBrowser !== false;
  const status = await proxyStatus();
  // Skip adult OS voices whenever Fish is on or object speech forbids the fallback.
  if (allowBrowser && status === false) await speakWithBrowser(text, lang);
}

const pause = (ms: number) => new Promise((r) => setTimeout(r, ms));

/**
 * Foreign word with that language's kid voice, then English name with Little Cloud's
 * default English kid voice (273667dee5fd4723a9f8a71c2cd4ab6c).
 * Never uses browser speech — that was the grown-man voice on Italian objects.
 */
export async function sayObject(obj: GameObjectDef, lang: LangCode): Promise<void> {
  const start = generation + 1;
  const noBrowser = { allowBrowser: false } as const;
  if (isEnglish(lang)) {
    await say(obj.name, lang, obj.id, obj.audio?.[lang] ?? obj.audio?.en, languageInfo(lang).voiceId, noBrowser);
    return;
  }
  await say(wordFor(obj, lang), lang, obj.id, obj.audio?.[lang], languageInfo(lang).voiceId, noBrowser);
  if (generation !== start) return;
  await pause(380);
  if (generation !== start) return;
  await say(obj.name, 'en', `${obj.id}-en`, obj.audio?.en, LITTLE_CLOUD_VOICE_ID, noBrowser);
}

/** Speak narration in the user's selected language (pass already-translated text). */
export function sayNarration(id: string, text: string, langOverride?: LangCode) {
  const lang = langOverride ?? useGame.getState().language;
  return say(text, lang, `narration-${id}`);
}

/** Prefetch clips for a page so taps feel instant. */
export async function prefetchObjects(objects: GameObjectDef[], lang: LangCode) {
  if (!audio.context) return;
  const files = await loadManifest();
  const voice = languageInfo(lang).voiceId;
  if (files.has(`${lang}/greeting`)) void audio.load(`/audio/${lang}/greeting.mp3`);
  for (const obj of objects) {
    if (files.has(`${lang}/${obj.id}`)) void audio.load(`/audio/${lang}/${obj.id}.mp3`);
    else if (config.ttsProxy) {
      void audio.load(ttsUrl(wordFor(obj, lang), lang, voice));
      if (!isEnglish(lang)) void audio.load(ttsUrl(obj.name, 'en', LITTLE_CLOUD_VOICE_ID));
    }
  }
}
